## The idea

A hash map is an **array of buckets**. A key's hash picks a bucket, and each bucket is a small **linked list** of the keys that landed there ("separate chaining"). To stay fast, keep the lists short: mix the key's bits so patterned keys spread out, and **double the array** when it gets 75% full. For many threads, split the map into several smaller maps each with its own lock ("lock striping"), so threads touching different keys rarely wait for each other.

## Step by step

1. Index(key): multiply the key by a large odd constant (mixes the bits), make it non-negative, take it modulo the array size.
2. Put: walk the bucket's list; if the key exists, update it. Otherwise add a new node at the front; if Count > Capacity × 0.75, resize.
3. Get: walk the bucket's list; return the value or −1.
4. Remove: walk the list keeping the previous node, and unlink the matching node.
5. Resize: make an array twice as big and move every node into its new bucket.
6. Striped: N maps + N lock objects; the key picks one; every call locks only that one.

## Worked example

**Input:** capacity 4; Put(1, 10), Put(5, 50), Get(5), Remove(1)

| Step | What happens |
|---|---|
| Put(1,10) | Index(1) = bucket 2 (say) → bucket 2: [1→10] |
| Put(5,50) | Index(5) = bucket 2 as well (a collision) → bucket 2: [5→50, 1→10] |
| Get(5) | walk bucket 2: first node is key 5 → 50 |
| Remove(1) | walk bucket 2: 5 (no), 1 (yes) → unlink it → bucket 2: [5→50] |

**Result:** Get(5) = 50; after Remove(1), Get(1) = -1

## Cost

Put, Get, Remove: O(1) on average (O(1) amortised for Put, counting resizes). Memory O(n).

## The code (C#, compiled and tested against every part of the question)

```csharp
// No Dictionary or HashSet inside — that is the exercise.
public class IntHashMap {
    private class Node {
        public int Key;
        public int Value;
        public Node Next;
    }

    private Node[] _buckets;
    private int _count;

    public IntHashMap(int capacity = 16) {
        _buckets = new Node[Math.Max(4, capacity)];
    }

    public int Count {
        get { return _count; }
    }

    public int Capacity {
        get { return _buckets.Length; }
    }

    // Mix the bits so keys like 1024, 2048, 3072 do not all land in the same bucket.
    private static int Index(int key, int size) {
        uint mixed = (uint)key * 2654435761u;
        return (int)(mixed % (uint)size);
    }

    public void Put(int key, int value) {
        int i = Index(key, _buckets.Length);
        for (Node node = _buckets[i]; node != null; node = node.Next) {
            if (node.Key == key) {           // already there: update
                node.Value = value;
                return;
            }
        }
        Node fresh = new Node();             // not there: add at the front of the bucket
        fresh.Key = key;
        fresh.Value = value;
        fresh.Next = _buckets[i];
        _buckets[i] = fresh;
        _count++;
        if (_count > _buckets.Length * 0.75) Resize();
    }

    public bool TryGet(int key, out int value) {
        for (Node node = _buckets[Index(key, _buckets.Length)]; node != null; node = node.Next) {
            if (node.Key == key) {
                value = node.Value;
                return true;
            }
        }
        value = 0;
        return false;
    }

    public int Get(int key) {
        int value;
        if (TryGet(key, out value)) return value;
        return -1;
    }

    public bool Remove(int key) {
        int i = Index(key, _buckets.Length);
        Node previous = null;
        for (Node node = _buckets[i]; node != null; node = node.Next) {
            if (node.Key == key) {
                if (previous == null) _buckets[i] = node.Next;   // it was the first node
                else previous.Next = node.Next;
                _count--;
                return true;
            }
            previous = node;
        }
        return false;
    }

    // Double the array and move every node to its new bucket.
    private void Resize() {
        Node[] old = _buckets;
        _buckets = new Node[old.Length * 2];
        foreach (Node head in old) {
            Node node = head;
            while (node != null) {
                Node next = node.Next;
                int i = Index(node.Key, _buckets.Length);
                node.Next = _buckets[i];
                _buckets[i] = node;
                node = next;
            }
        }
    }
}

// Many threads: N smaller maps, each with its own lock. A key always uses the same stripe.
public class StripedIntHashMap {
    private readonly IntHashMap[] _maps;
    private readonly object[] _locks;

    public StripedIntHashMap(int stripes = 16) {
        _maps = new IntHashMap[stripes];
        _locks = new object[stripes];
        for (int s = 0; s < stripes; s++) {
            _maps[s] = new IntHashMap();
            _locks[s] = new object();
        }
    }

    private int StripeOf(int key) {
        return (int)(((uint)key * 2654435761u) % (uint)_maps.Length);
    }

    public void Put(int key, int value) {
        int s = StripeOf(key);
        lock (_locks[s]) { _maps[s].Put(key, value); }
    }

    public int Get(int key) {
        int s = StripeOf(key);
        lock (_locks[s]) { return _maps[s].Get(key); }
    }

    public bool Remove(int key) {
        int s = StripeOf(key);
        lock (_locks[s]) { return _maps[s].Remove(key); }
    }

    // Read-modify-write inside ONE lock, so no increment is lost.
    public void AddOrIncrement(int key, int by) {
        int s = StripeOf(key);
        lock (_locks[s]) {
            int current;
            if (!_maps[s].TryGet(key, out current)) current = 0;
            _maps[s].Put(key, current + by);
        }
    }

    public int Count {
        get {
            int total = 0;
            for (int s = 0; s < _maps.Length; s++) {
                lock (_locks[s]) { total += _maps[s].Count; }
            }
            return total;
        }
    }
}
